using System;
using System.IO;
using System.Linq;
using System.Collections;
using System.Collections.Generic;
using IdleIntelligence.Core;
using IdleIntelligence.Runtime;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.SceneManagement;
using UnityEngine.TestTools;
namespace IdleIntelligence.PlayTests
{
 public sealed class RewardMotionV2Tests
 {
  const string Output="/tmp/idle-reward-v2-review";GameRuntime game;string save;
  [UnitySetUp] public IEnumerator Setup(){Directory.CreateDirectory(Output);save=Path.Combine(Path.GetTempPath(),"idle-reward-v2-"+Guid.NewGuid(),"save.json");Directory.CreateDirectory(Path.GetDirectoryName(save));GameRuntime.SavePathOverride=save;yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();PortraitGameView.Set(390,846);yield return null;yield return null;}
  [UnityTearDown]public IEnumerator Cleanup(){if(game!=null)UnityEngine.Object.Destroy(game.gameObject);yield return null;GameRuntime.SavePathOverride=null;}
  void Click(string name){var b=GameObject.Find(name)?.GetComponent<Button>();Assert.That(b,Is.Not.Null,name);Assert.That(b.interactable,Is.True,name);b.onClick.Invoke();}
  void Prepared(){game.Act(s=>{var n=s.Copy();n.Legacy.prepared=true;n.Retention.aiName="AURA";n.Retention.gems=100000;n.Prestige.resets=1;n.Prestige.Total=ScientificNumber.From(1000);n.Story.enabled=false;n.Story.open=null;n.Story.queue=Array.Empty<string>();n.Story.tutorial="skipped";n.Story.seen=NarrativeCatalog.Dialogues.Select(d=>d.Id).ToArray();return n;});var mark=WorkshopUIFactory.Label("IsolatedReviewBanner",game.Content.GetComponentInParent<Canvas>().transform,"ISOLIERTER TESTSTAND",11,20);UnityEngine.Object.DestroyImmediate(mark.GetComponent<LayoutElement>());mark.alignment=TextAnchor.MiddleCenter;mark.color=GameTheme.Gold;var mr=mark.rectTransform;mr.anchorMin=mr.anchorMax=new Vector2(.5f,1);mr.pivot=new Vector2(.5f,1);mr.anchoredPosition=new Vector2(0,-6);mr.sizeDelta=new Vector2(300,20);var mc=mark.gameObject.AddComponent<Canvas>();mc.overrideSorting=true;mc.sortingOrder=30000;Debug.Log("ISOLATED PREPARED REVIEW: paid chest and gumball use actual saved receipts; normal player data untouched.");}
  void Saved(){var read=new AtomicSaveStore(save,new UnitySaveCodec()).Load(game.State.SavedAt);Assert.That(read.Writable,Is.True,read.Message);Assert.That(read.State.Retention.gems,Is.EqualTo(game.State.Retention.gems));Assert.That(read.State.Rewards.shopRevision,Is.EqualTo(game.State.Rewards.shopRevision));Assert.That(read.State.Capsules.draws,Is.EqualTo(game.State.Capsules.draws));CollectionAssert.AreEqual(game.State.Workshop.components,read.State.Workshop.components);}
  IEnumerator Record(string name,string action,float duration){string folder=Output+"/"+name;Directory.CreateDirectory(folder);var times=new List<string>();int frame=0;bool done=false;float start=Time.realtimeSinceStartup;var listener=game.GetComponent<AudioListener>();if(listener!=null)listener.enabled=false;var node=new GameObject("RewardReviewAudio",typeof(AudioListener),typeof(ReviewAudioCapture));node.transform.SetParent(game.transform);var audio=node.GetComponent<ReviewAudioCapture>();game.Audio.Unlock();audio.Begin();long revision=0,draws=0;
   while(Time.realtimeSinceStartup-start<duration){if(!done&&Time.realtimeSinceStartup-start>.5f){done=true;Click(action);Saved();revision=game.State.Rewards.shopRevision;draws=game.State.Capsules.draws;}times.Add((Time.realtimeSinceStartup-start).ToString("R",System.Globalization.CultureInfo.InvariantCulture));if(name=="gumball"&&done){var current=game.GetComponent<RewardPresentation>().Current;float age=current.Elapsed;if(age>.8f&&age<1.3f){Assert.That(current.Capsule.gameObject.activeInHierarchy,Is.True);Assert.That(current.Capsule.color.a,Is.EqualTo(1),"Previous chest must not leave the dispensed capsule transparent");}}WorkshopTests.Capture(390,846,folder+"/"+(frame++).ToString("D4")+".png");yield return null;}
   audio.Save(folder);File.WriteAllLines(folder+"/times.txt",times);Assert.That(game.State.Rewards.shopRevision,Is.EqualTo(revision));Assert.That(game.State.Capsules.draws,Is.EqualTo(draws));Assert.That(game.GetComponent<RewardPresentation>().Current.IsAnimating,Is.False);UnityEngine.Object.Destroy(node);
  }

  [UnityTest]public IEnumerator ActualRewardsFitBothLanguagesWidthsAndRapidCancel(){Prepared();yield return null;int tier=0;foreach(string language in new[]{"de","en"}){game.Act(s=>SettingsRules.Change(s,"language",language));foreach(int width in new[]{320,390,430}){PortraitGameView.Set(width,width==320?694:width==390?846:932);yield return null;yield return null;game.Show("market");yield return null;Click("MarketOffer-chest:"+new[]{"common","rare","epic","legendary"}[tier++%4]);Saved();yield return new WaitForSecondsRealtime(1.4f);var stage=game.GetComponent<RewardPresentation>().Current;Assert.That(stage.Chest.Frame,Is.EqualTo(5));var chestBounds=new Vector3[4];stage.Body.rectTransform.GetWorldCorners(chestBounds);foreach(var label in stage.Rewards.GetComponentsInChildren<Text>().Where(t=>t.name.StartsWith("ReceiptAmount")&&t.canvasRenderer.GetAlpha()>.95f)){var bounds=new Vector3[4];label.rectTransform.GetWorldCorners(bounds);Assert.That(chestBounds[1].y,Is.LessThan(bounds[0].y-2),"Settled open chest must sit clear below actual reward labels");}WorkshopTests.Capture(width,Screen.height,Output+"/chest-"+language+"-"+width+".png");stage.Cancel();game.Show("gems");yield return null;Click("GemPage-capsule");yield return null;Click("CapsuleDraw");Saved();yield return new WaitForSecondsRealtime(.98f);Assert.That(stage.Capsule.gameObject.activeInHierarchy,Is.True);Assert.That(stage.Capsule.color.a,Is.EqualTo(1));WorkshopTests.Capture(width,Screen.height,Output+"/capsule-drop-"+language+"-"+width+".png");yield return new WaitForSecondsRealtime(1.4f);WorkshopTests.Capture(width,Screen.height,Output+"/capsule-result-"+language+"-"+width+".png");stage.Cancel();}}
   Click("CapsuleDraw");yield return null;Click("CapsuleDraw");long draws=game.State.Capsules.draws;game.Show("hardware");yield return null;Assert.That(game.GetComponent<RewardPresentation>().Current.IsAnimating,Is.False);Assert.That(game.State.Capsules.draws,Is.EqualTo(draws));game.Act(s=>SettingsRules.Change(s,"toggle-effects"));game.Show("gems");yield return null;Click("GemPage-capsule");yield return null;Click("CapsuleDraw");Assert.That(game.GetComponent<RewardPresentation>().Current.IsAnimating,Is.False);Saved();yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();Assert.That(game.State.Capsules.draws,Is.EqualTo(draws+1));Assert.That(game.GetComponent<RewardPresentation>().Current,Is.Null);
  }
  [UnityTest] public IEnumerator RecordActualChestThenGumball(){Prepared();yield return null;game.Show("market");yield return null;yield return Record("chest","MarketOffer-chest:legendary",4.3f);game.Show("gems");yield return null;Click("GemPage-capsule");yield return null;yield return Record("gumball","CapsuleDraw",4.8f);Saved();}
  [UnityTest] public IEnumerator BubbleContainsActionsAndKeepsGameUsableAtEveryWidth(){
   foreach(string language in new[]{"de","en"}){game.Act(s=>SettingsRules.Change(s,"language",language));foreach(int width in new[]{320,390,430}){PortraitGameView.Set(width,width==320?694:width==390?846:932);yield return null;yield return null;Canvas.ForceUpdateCanvases();var coach=UnityEngine.Object.FindFirstObjectByType<MiraCoach>();Assert.That(coach,Is.Not.Null);var bubble=coach.transform.Find("SpeechBubble");Assert.That(coach.Skip.transform.IsChildOf(bubble),Is.True);Assert.That(coach.Confirm.transform.IsChildOf(bubble),Is.True);Assert.That(coach.Panel.rect.height,Is.LessThan(250));Assert.That(coach.Speech.preferredHeight,Is.LessThanOrEqualTo(coach.Speech.rectTransform.rect.height+1),coach.Speech.text);Assert.That(coach.Skip.GetComponent<RectTransform>().rect.height,Is.GreaterThanOrEqualTo(44));WorkshopTests.Capture(width,Screen.height,Output+"/mira-name-"+language+"-"+width+".png");}}
   GameObject.Find("StoryNameInput").GetComponent<InputField>().text="AURA";Click("StoryChooseName");yield return null;foreach(string language in new[]{"de","en"}){game.Act(s=>SettingsRules.Change(s,"language",language));foreach(int width in new[]{320,390,430}){PortraitGameView.Set(width,width==320?694:width==390?846:932);yield return null;yield return null;Canvas.ForceUpdateCanvases();var coach=UnityEngine.Object.FindFirstObjectByType<MiraCoach>();Assert.That(coach.Next.transform.IsChildOf(coach.transform.Find("SpeechBubble")),Is.True);Assert.That(coach.Speech.preferredHeight,Is.LessThanOrEqualTo(coach.Speech.rectTransform.rect.height+1));WorkshopTests.Capture(width,Screen.height,Output+"/mira-dialog-"+language+"-"+width+".png");}}
   Click("StorySkipCurrent");yield return null;Saved();yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();Assert.That(game.State.Retention.aiName,Is.EqualTo("AURA"));
  }
 }
}
